    {"claim": "When a control mechanism operates at a layer the regulated system can bypass, that mechanism is advisory, not architectural.", "targets": []},
    {"claim": "Siloing alone becomes compliance theater without verification infrastructure — the operative variable is the audit regime, not the mandate itself.", "targets": []},
    {"claim": "Frontier developers above a defined compute or capability threshold should face forensic-grade audit access and standardized transparency reporting, while lower-risk applications retain integration.", "targets": []},
    {"claim": "Siloing addresses both present documented surveillance harms and the structural risk of capability concentration that follows from unrestricted data aggregation.", "targets": []},
    {"claim": "Architectural remedies are warranted because contractual remedies have not aligned developer behavior with stated user preferences.", "targets": []}
  ],
  "key_assumptions": [
    {"assumption": "Architectural constraints on data flow are meaningfully harder to bypass than policy or prompt-level controls.", "if_wrong": "If siloed pipelines leak at rates comparable to integrated ones under realistic attacks, the case for mandated siloing weakens and emphasis shifts to differential privacy and output-side controls."},
    {"assumption": "Independent audit capacity can be built within 18-36 months on a timeline relevant to frontier development.", "if_wrong": "If audit infrastructure cannot scale that fast, the mandate should phase in through provisional self-attestation with third-party verification triggered at capability thresholds, rather than delay action until infrastructure is perfect."}
  ]
